package dev.argon.esexpr.tests;

import dev.argon.esexpr.*;

import com.google.errorprone.annotations.MustBeClosed;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableMap;
import org.apache.commons.io.FilenameUtils;
import tools.jackson.core.type.TypeReference;
import tools.jackson.databind.DatabindException;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.module.SimpleModule;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

public class BinaryEncodingTest {
	@ParameterizedTest
	@MethodSource("fileProvider")
	public void binaryEncoding(Path jsonPath) throws Exception {
		var esxbPath = jsonPath
			.resolveSibling(FilenameUtils.removeExtension(jsonPath.getFileName().toString()) + ".esxb");

		var jsonValue = parseJson(Files.readString(jsonPath));
		var esxbValue = parseEsxb(Files.readAllBytes(esxbPath));
		var reencodedValue = new ArrayList<ESExpr>();
		for(var expr : esxbValue) {
			reencodedValue.add(parseEsxb1(encodeEsxb(expr)));
		}

		assertEquals(jsonValue, esxbValue);
		assertEquals(esxbValue, reencodedValue);
	}

	@Test
	public void rawJsonIntegersPreservePrecision() throws Exception {
		var huge = BigInteger.ONE.shiftLeft(256);
		for(var value : List.of(
			BigInteger.ZERO,
			BigInteger.valueOf(42),
			BigInteger.valueOf(-42),
			BigInteger.ONE.shiftLeft(64),
			huge,
			huge.negate()
		)) {
			var expr = new ESExpr.Int(value);
			assertEquals(List.of(expr), parseJson(value.toString()));
			assertEquals(List.of(expr), parseJson("[" + value + "]"));
			assertEquals(List.of(new ESExpr.Str(value.toString())), parseJson("\"" + value + "\""));
			assertEquals(
				List.of(new ESExpr.Constructor("nested", ImmutableList.of(expr), ImmutableMap.of("value", expr))),
				parseJson(
					"{\"constructor_name\":\"nested\",\"args\":[" + value + "],\"kwargs\":{\"value\":" + value + "}}"
				)
			);
		}
		assertThrows(DatabindException.class, () -> parseJson("1.5"));
	}

	@Test
	public void wideJsonIntegersPreservePrecision() throws Exception {
		assertEquals(
			List.of(new ESExpr.Array64(org.eclipse.collections.api.factory.primitive.LongLists.immutable.of(-1L))),
			parseJson("{\"array64\":[18446744073709551615]}")
		);
		assertEquals(
			List.of(new ESExpr.Array128(org.eclipse.collections.api.factory.primitive.LongLists.immutable.of(0L, 1L))),
			parseJson("{\"array128\":[18446744073709551616]}")
		);
		var level = BigInteger.ONE.shiftLeft(256);
		assertEquals(List.of(new ESExpr.Null(level)), parseJson("{\"null\":" + level + "}"));
	}

	private List<ESExpr> parseJson(String value) throws Exception {
		var mapper = new ObjectMapper();

		var module = new SimpleModule();
		module.addDeserializer(ESExpr.class, new ESExprJsonDeserializer());
		mapper = mapper.rebuild().addModule(module).build();

		List<ESExpr> res;
		try {
			res = mapper.readValue(value, new TypeReference<List<ESExpr>>() {});
		}
		catch(DatabindException _) {
			res = List.of(mapper.readValue(value, ESExpr.class));
		}

		return res.stream().map(e -> {
			if(e == null) {
				return new ESExpr.Null(BigInteger.ZERO);
			}
			else {
				return e;
			}
		}).toList();
	}

	private List<ESExpr> parseEsxb(byte[] value) throws Exception {
		var reader = new ESExprBinaryReader(new ByteArrayInputStream(value));
		return reader.readAll().toList();
	}

	private ESExpr parseEsxb1(byte[] value) throws Exception {
		var exprs = parseEsxb(value);

		assertEquals(1, exprs.size());
		return exprs.getFirst();
	}

	private byte[] encodeEsxb(ESExpr expr) throws Exception {
		var os = new ByteArrayOutputStream();
		var writer = new ESExprBinaryWriter(os);
		writer.write(expr);
		return os.toByteArray();
	}

	@MustBeClosed
	public static Stream<Path> fileProvider() throws IOException {
		Path directory = Paths.get("../../tests");
		return Files.list(directory).filter(Files::isRegularFile)
			.filter(p -> FilenameUtils.getExtension(p.getFileName().toString()).equals("json"));
	}
}
